async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: {type: 'list_sessions'; limit?: number; before?: {updatedAt: string; sessionId: string}}
): Promise<void> {
  if (!sessionStore?.listFor) {
    log.debug('ws', 'store has no listFor, answering empty list');
    sendSessionList(ws, []);
    return;
  }

  const options: SessionListOptions = {limit: message.limit, before: message.before};
  try {
    const sessions = await sessionStore.listFor(session.userId, options);
    sendSessionList(ws, sessions);
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'listFor failed', {userId: session.userId, error: message, sessionId: session.sessionId});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

