    it('does not resurrect an entry the client only ever saw skipped', async () => {
      const h = harness([SUPPRESS, text('hidden'), STOP, SUPPRESS]);

      await h.send();

      expect(h.frames()).toEqual(['upsert 0 user "hello"', 'skip 1', 'stream_end']);
