      expect({frames: h.frames(), answer, after}).toMatchObject({
        frames: [
          'upsert 0 user "hello"',
          'upsert 1 assistant ""',
          'delta 1 "before"',
          'commit 1',
          'upsert 1 assistant ""',
          'skip 2',
          'stream_end',
